import type { FunctionModel, SourceModel, TypeModel } from './types.js';

export function generateRust(model: SourceModel): string {
  const lines: string[] = [
    '// Generated by ts-to-rust-foundry-starter',
    '// This is a starter artifact, not a semantics-complete translation.',
    '#![allow(dead_code)]',
    ''
  ];

  const uses = collectUses(model);
  if (uses.size > 0) {
    for (const useLine of [...uses].sort()) {
      lines.push(useLine);
    }
    lines.push('');
  }

  for (const note of model.notes) {
    lines.push(`// NOTE: ${note}`);
  }
  if (model.notes.length > 0) {
    lines.push('');
  }

  for (const type of model.types) {
    lines.push(...emitType(type));
    lines.push('');
  }
  for (const fn of model.functions) {
    lines.push(...emitTopLevelFunction(fn));
    lines.push('');
  }
  return lines.join('\n').trimEnd() + '\n';
}

function emitType(type: TypeModel): string[] {
  switch (type.kind) {
    case 'enum':
      return emitEnum(type);
    case 'interface':
      return emitInterface(type);
    case 'class':
      return emitClass(type);
    case 'typeAlias':
      return emitTypeAlias(type);
  }
}

function emitEnum(type: TypeModel): string[] {
  const lines = ['#[derive(Debug, Clone, PartialEq)]', `pub enum ${type.name} {`];
  for (const member of type.members ?? []) {
    lines.push(`    ${pascalize(member)},`);
  }
  lines.push('}');
  return lines;
}

function emitTypeAlias(type: TypeModel): string[] {
  return [`pub type ${type.name} = ${mapType(type.targetType ?? 'serde_json::Value')};`];
}

function emitInterface(type: TypeModel): string[] {
  const lines: string[] = [];
  if (type.properties.length > 0) {
    lines.push('#[derive(Debug, Clone, PartialEq)]');
    lines.push(`pub struct ${type.name} {`);
    for (const prop of type.properties) {
      lines.push(`    pub ${snakeCase(prop.name)}: ${wrapOptional(mapType(prop.type), prop.optional)},`);
    }
    lines.push('}');
  }
  if (type.methods.length > 0) {
    if (lines.length > 0) lines.push('');
    lines.push(`pub trait ${type.name}Behavior {`);
    for (const method of type.methods) {
      const params = method.parameters.map((p) => `${snakeCase(cleanOptional(p.name))}: ${mapType(p.type)}`).join(', ');
      const selfPrefix = params.length > 0 ? '&self, ' : '&self';
      lines.push(`    fn ${snakeCase(method.name)}(${selfPrefix}${params}) -> ${mapType(method.returnType)};`);
    }
    lines.push('}');
  }
  return lines.length > 0 ? lines : [`// Interface ${type.name} had no mappable members.`];
}

function emitClass(type: TypeModel): string[] {
  const lines: string[] = ['#[derive(Debug, Clone, PartialEq)]', `pub struct ${type.name} {`];
  for (const prop of type.properties) {
    lines.push(`    pub ${snakeCase(prop.name)}: ${wrapOptional(mapType(prop.type), prop.optional)},`);
  }
  lines.push('}', '');
  lines.push(`impl ${type.name} {`);
  if (type.methods.length === 0) {
    lines.push('    pub fn new() -> Self {', '        Self {', '        }', '    }');
  }
  for (const method of type.methods) {
    lines.push(...emitImplMethod(method, type.properties.length > 0));
  }
  lines.push('}');
  return lines;
}

function emitPseudocodeBlock(
  name: string,
  kind: string,
  returns: string,
  params: string,
  steps: string[],
  indent: string
): string[] {
  const sep = '─'.repeat(Math.max(0, 56 - name.length));
  const out = [
    `${indent}// PSEUDOCODE [${name}] ${sep}`,
    `${indent}// Kind: ${kind}`,
    `${indent}// Returns: ${returns}`,
  ];
  if (params) out.push(`${indent}// Params: ${params}`);
  if (steps.length) {
    out.push(`${indent}//`);
    out.push(`${indent}// Steps:`);
    for (const step of steps) out.push(`${indent}//   - ${step}`);
  }
  out.push(`${indent}// ${'─'.repeat(70)}`);
  return out;
}

function emitImplMethod(method: FunctionModel, hasFields: boolean): string[] {
  const lines: string[] = [];
  const isCtor = method.kind === 'constructor';
  if (isCtor) {
    lines.push('    pub fn new() -> Self {');
    lines.push('        Self {');
    if (!hasFields) {
      lines.push('        }');
    } else {
      lines.push('            // TODO: initialize fields');
      lines.push('        }');
    }
    lines.push('    }');
    return lines;
  }
  const params = method.parameters
    .map((p) => `${snakeCase(cleanOptional(p.name))}: ${wrapOptional(mapType(p.type), p.name.endsWith('?'))}`)
    .join(', ');
  const receiver = method.static ? '' : '&self';
  const signature = [receiver, params].filter(Boolean).join(', ');
  lines.push(`    pub fn ${snakeCase(method.name)}(${signature}) -> ${mapType(method.returnType)} {`);
  if (method.kind === 'component' || method.jsxLike) {
    lines.push('        // TSX/JSX component detected. Choose an explicit Rust UI target before implementation.');
  }
  lines.push(...emitPseudocodeBlock(
    method.name, method.kind, method.returnType,
    method.parameters.map((p) => `${p.name}: ${p.type}`).join(', '),
    method.pseudocode ?? [], '        '
  ));
  lines.push(`        todo!("implement: ${snakeCase(method.name)}");`);
  lines.push('    }');
  return lines;
}

function emitTopLevelFunction(fn: FunctionModel): string[] {
  const lines: string[] = [];
  const params = fn.parameters
    .map((p) => `${snakeCase(cleanOptional(p.name))}: ${wrapOptional(mapType(p.type), p.name.endsWith('?'))}`)
    .join(', ');
  lines.push(`pub fn ${snakeCase(fn.name)}(${params}) -> ${mapType(fn.returnType)} {`);
  if (fn.kind === 'component' || fn.jsxLike) {
    lines.push('    // Component-like function detected. This should target a Rust UI framework explicitly.');
  }
  lines.push(...emitPseudocodeBlock(
    fn.name, fn.kind, fn.returnType,
    fn.parameters.map((p) => `${p.name}: ${p.type}`).join(', '),
    fn.pseudocode ?? [], '    '
  ));
  lines.push(`    todo!("implement: ${snakeCase(fn.name)}");`);
  lines.push('}');
  return lines;
}

function collectUses(model: SourceModel): Set<string> {
  const uses = new Set<string>();
  const allTexts = [
    ...model.types.flatMap((type) => [
      ...type.properties.map((prop) => prop.type),
      ...type.methods.flatMap((method) => [method.returnType, ...method.parameters.map((param) => param.type)]),
      ...(type.targetType ? [type.targetType] : [])
    ]),
    ...model.functions.flatMap((fn) => [fn.returnType, ...fn.parameters.map((param) => param.type)])
  ];
  if (allTexts.some((value) => /(^|\W)(Date)(\W|$)/.test(value))) {
    uses.add('use chrono::{DateTime, Utc};');
  }
  if (allTexts.some((value) => value.includes('Record<') || value.includes('{['))) {
    uses.add('use std::collections::HashMap;');
  }
  return uses;
}

function mapType(typeText: string): string {
  const normalized = typeText.replace(/\s+/g, ' ').trim();
  if (!normalized || normalized === 'void') return '()';
  if (normalized === 'string') return 'String';
  if (normalized === 'number') return 'f64';
  if (normalized === 'boolean') return 'bool';
  if (normalized === 'unknown' || normalized === 'any') return 'serde_json::Value';
  if (normalized === 'Date') return 'DateTime<Utc>';
  if (/^Promise<(.+)>$/.test(normalized)) {
    const inner = normalized.replace(/^Promise<(.+)>$/, '$1');
    return mapType(inner);
  }
  if (/^Array<(.+)>$/.test(normalized)) {
    const inner = normalized.replace(/^Array<(.+)>$/, '$1');
    return `Vec<${mapType(inner)}>`;
  }
  if (/^ReadonlyArray<(.+)>$/.test(normalized)) {
    const inner = normalized.replace(/^ReadonlyArray<(.+)>$/, '$1');
    return `Vec<${mapType(inner)}>`;
  }
  if (/^Record<\s*string\s*,\s*(.+)>$/.test(normalized)) {
    const inner = normalized.replace(/^Record<\s*string\s*,\s*(.+)>$/, '$1');
    return `HashMap<String, ${mapType(inner)}>`;
  }
  if (normalized.endsWith('[]')) {
    return `Vec<${mapType(normalized.slice(0, -2))}>`;
  }
  if (normalized.includes('|')) {
    const parts = normalized.split('|').map((part) => part.trim()).filter(Boolean);
    const nonNull = parts.filter((part) => part !== 'undefined' && part !== 'null');
    if (nonNull.length === 1 && nonNull.length !== parts.length) {
      return `Option<${mapType(nonNull[0])}>`;
    }
    return 'serde_json::Value';
  }
  if (normalized.startsWith('{') || normalized.includes('=>')) {
    return 'serde_json::Value';
  }
  return normalized.replace(/[^A-Za-z0-9_<>, ]/g, '') || 'serde_json::Value';
}

function wrapOptional(typeText: string, optional: boolean): string {
  return optional ? `Option<${typeText}>` : typeText;
}

function snakeCase(value: string): string {
  return value
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/[^A-Za-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase() || 'unnamed';
}

function pascalize(value: string): string {
  return value
    .replace(/[^A-Za-z0-9]+/g, ' ')
    .split(' ')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('') || 'Unknown';
}

function cleanOptional(value: string): string {
  return value.replace(/\?$/, '');
}
